{
  "html": "<div class="e3" data-ui-unit="E3" role="group" aria-label="상담 분야">
  <button class="chip chip-selected" disabled type="button">전체</button>
  <button class="chip" disabled type="button">커리어</button>
  <button class="chip" disabled type="button">자소서</button>
  <button class="chip" disabled type="button">면접</button>
</div>",
  "css": ".e3 {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  min-height: 36px;
  padding: 0 12px;
}

.chip {
  height: 36px;
  border-radius: 18px;
  padding: 0 12px;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.57;
  white-space: nowrap;
  cursor: default;
}

.chip-selected {
  background-color: var(--ink);
  color: #fff;
}

.chip:not(.chip-selected) {
  background-color: var(--surface);
  color: var(--muted);
}"
}
